function preset(type){if(net?.active){toast('Бірлескен миссияда тізбекті өздерің құрастырыңдар.');return;}avatar.path=[];avatar.done=null;held=null;selected=null;pending=null;wires=[];wireSerial=0;powered=true;switchClosed=true;voltage=12;defs.forEach(c=>{if(c.kind==='lamp'){c.r=12;c.enabled=true;c.placed=false;c.pos=[...c.home];}});parts.B.pos=[-2.5,Y,-.65];parts.K.placed=true;parts.K.pos=[-1.8,Y,.91];parts.L1.placed=true;parts.L1.pos=[-.55,Y,-.7];parts.L2.placed=true;parts.L2.pos=[1.15,Y,-.7];const pairs=type==='series'?[['Ba','Ka'],['Kb','L1a'],['L1b','L2a'],['L2b','Bb']]:type==='parallel'?[['Ba','Ka'],['Kb','L1a'],['Kb','L2a'],['L1b','Bb'],['L2b','Bb']]:[['Ba','Ka'],['Kb','L1a'],['L1b','L2a'],['L1b','L3a'],['L2b','Bb'],['L3b','Bb']];if(type==='mixed'){parts.L3.placed=true;parts.L3.pos=[1.15,Y,.91];}pairs.forEach(([a,b])=>wires.push({a,b,id:++wireSerial}));avatar.pos=[0,0,4.2];avatar.angle=Math.PI;setView('bench');setTool('move');selectPart(null);recalc();toast(types[type]+': құралдар мен сымдарды еркін өзгерте аласыз.');}
function togglePower(){if(net?.active){net.send('power');return;}powered=!powered;sound?.play('power');recalc();}
function toggleSwitch(){if(net?.active){net.send('switch');return;}if(parts.K.placed){switchClosed=!switchClosed;sound?.play('switch');recalc();}}
function clearCircuit(){if(net?.active){net.send('clear');return;}wires=[];pending=null;powered=false;recalc();toast('Сымдар алынды.');}
function removeWire(id){if(net?.active){net.send('removeWire',{id});return;}wires=wires.filter(w=>w.id!==id);recalc();}
function changeVoltage(value){if(net?.active){net.send('voltage',{value});return;}voltage=value;recalc();}
function changeResistance(value){if(!parts[selected]||!['lamp','resistor','motor'].includes(parts[selected].kind))return;if(net?.active){net.send('resistance',{id:selected,value});return;}parts[selected].r=value;$('resValue').textContent=value+' Ом';recalc();}
function breakSelected(enabled){if(!parts[selected]||!['lamp','resistor','motor'].includes(parts[selected].kind))return;if(net?.active){net.send('break',{id:selected,enabled});return;}parts[selected].enabled=enabled;recalc();}
function drawPlot(){const c=$('plot'),w=c.clientWidth||300,h=99,d=Math.min(devicePixelRatio||1,2);if(c.width!==Math.round(w*d)||c.height!==Math.round(h*d)){c.width=Math.round(w*d);c.height=Math.round(h*d);}const x=c.getContext('2d');if(!x)return;x.setTransform(d,0,0,d,0,0);x.clearRect(0,0,w,h);const max=Math.max(1,...history.map(o=>o.i))*1.15,left=32,right=w-8,top=7,bottom=77;x.font='10px "Segoe UI", Arial';x.textAlign='right';x.fillStyle='#a8bbc6';x.strokeStyle='#304854';x.lineWidth=1;for(let j=0;j<=2;j++){let y=bottom-(bottom-top)*j/2;x.beginPath();x.moveTo(left,y);x.lineTo(right,y);x.stroke();x.fillText(fmt(max*j/2,1),left-5,y+3);}x.textAlign='left';x.fillText('−20 с',left,94);x.textAlign='right';x.fillText('қазір',right,94);if(!history.length)return;x.beginPath();history.forEach((o,i)=>{const px=right-(clock-o.t)/20*(right-left),py=bottom-o.i/max*(bottom-top);if(i===0)x.moveTo(px,py);else x.lineTo(px,py);});x.strokeStyle='#7bf0d4';x.lineWidth=2;x.stroke();const last=history.at(-1);x.beginPath();x.arc(right-(clock-last.t)/20*(right-left),bottom-last.i/max*(bottom-top),3,0,Math.PI*2);x.fillStyle='#a1f6e1';x.fill();}
function record(){const r={t:new Date().toLocaleTimeString('kk-KZ'),voltage,sourceOn:powered,switchClosed,type:solution.type,short:solution.short,closed:solution.closed,u:solution.u,i:solution.i,req:solution.req,power:solution.power,lamps:JSON.parse(JSON.stringify(solution.lamps)),resistors:defs.filter(c=>['lamp','resistor','ammeter','voltmeter','motor'].includes(c.kind)).map(c=>({id:c.id,r:c.kind==='voltmeter'?Infinity:c.r,placed:c.placed,enabled:c.enabled!==false})),wires:wires.map(w=>[w.a,w.b])};records.push(r);$('recordCount').textContent=records.length;recalc();toast('№'+records.length+' өлшеу журналға жазылды.');}
