function download(){const header=['№','Уақыт','Қосылу','Қуат қосулы','Кілт жабық','Қойылған U (В)','Шығыс U (В)','I (А)','R (Ом)','P (Вт)',...['L1','L2','L3','R1','A','V','M'].flatMap(id=>[id+' үстелде',id+' бүтін',id+' R (Ом)',id+' U (В)',id+' I (А)',id+' P (Вт)']),'Сымдар'];const rows=records.map((r,i)=>[i+1,r.t,types[r.type],r.sourceOn,r.switchClosed,r.voltage,r.u,r.i,Number.isFinite(r.req)?r.req:'Infinity',r.power,...r.resistors.flatMap(c=>[c.placed,c.enabled,c.r,r.lamps[c.id].floating?'':r.lamps[c.id].u,r.lamps[c.id].floating?'':r.lamps[c.id].i,r.lamps[c.id].p]),r.wires.map(w=>w.join('↔')).join(' | ')]);const quote=v=>'"'+String(v).replace(/"/g,'""')+'"';const csv='\uFEFF'+[header,...rows].map(r=>r.map(quote).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download='Elektr_Lab_olsheuler.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
