function takeAim(){const h=hit(screenW/2,screenH/2,'part'),c=h&&parts[h.id];if(c&&c.id!=='B'&&reach(c))pickup(c.id);else toast('Құралды нысанаға алыңыз.');}
function gateVisible(){const p=project([0,1.65,10.7]);return !!p&&Math.hypot(p[0]-screenW/2,p[1]-screenH/2)<120&&Math.hypot(avatar.pos[0],avatar.pos[2]-9.3)<3;}
function goGate(near=false){if(!net?.active){toast('Бөлмелерге бірге өту үшін QR сессиясына кіріңіз.');return;}if(!net.state?.goal.ok){toast('Алдымен ортақ тапсырманы орындаңдар.');return;}if(held){toast('Алдымен қолдағы құралды қойыңыз.');return;}if(near&&Math.hypot(avatar.pos[0],avatar.pos[2]-9.3)<2.3){net.ready();return;}releaseMouse();route([net.playerId==='p1'?-.6:.6,0,9.3],()=>{desired.yaw=Math.PI;desired.pitch=-.06;net.ready();});}
function drawGate(dt){const accent=[0x7bead3,0x9aacff,0xffcf83][net?.state?.stage||0];for(const x of [-9,9])box([x,4.25,-9.84],[3.7,.15,.08],accent,0,.8);const open=!!net?.state?.goal.ok;doorOpen+=(Number(open)-doorOpen)*Math.min(1,dt*3);const c=open?0x66e5ab:0xdeb264;box([-1.55,1.65,10.8],[.16,3.3,.3],0x254a5b);box([1.55,1.65,10.8],[.16,3.3,.3],0x254a5b);box([0,3.31,10.8],[3.25,.16,.3],c,0,.65);for(const side of [-1,1]){box([side*(.75+doorOpen*1.25),1.6,10.8],[1.46,3.2,.1],0x426b74);box([side*(.75+doorOpen*1.25),1.95,10.72],[1.02,1.2,.025],0x8eb6bc);box([side*.14,1.42,10.57],[.055,.32,.08],c,0,.5);}}
function gateLabel(){label('roomStage',net?.active?net.state?.goal.title:'ЭЛЕКТР LAB · ЖЕКЕ ЖАТТЫҒУ',[2.5,4.5,-9.65]);const text=net?.state?.finished?'МИССИЯ ОРЫНДАЛДЫ':net?.state?.goal.ok?'ЕСІК АШЫҚ · ЕКЕУІҢ БІРГЕ ӨТІҢДЕР':'КЕЛЕСІ БӨЛМЕ · ТАПСЫРМАНЫ ОРЫНДА';const p=label('exit',text,[0,3.65,10.65]);const target=project([0,1.65,10.7]);if(p&&target)hitTargets.push({kind:'gate',id:'gate',p:target,r:75});for(const peer of peers)if(peer.present)label('peer'+peer.id,peer.name,[(peer.view||peer.pos)[0],2.62,(peer.view||peer.pos)[2]]);}
